  animation:aiLogoSweep202606 .65s ease var(--sweep-delay,1.55s) both;
}
@keyframes aiLogoDrawSegment202606{to{stroke-dasharray:var(--segment-length) var(--path-length);}}
@keyframes aiLogoFillIn202606{to{opacity:1;}}
